using System.Reflection;using TownOfHost;using TownOfHost.Templates;using UnityEngine;
class Program {
static int passed,failed;static void Check(bool b,string why="assertion failed"){if(!b)throw new Exception(why);}static object Field(Type t,string n)=>t.GetField(n,BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);static GameObject Root=>(GameObject)Field(typeof(YouTubeAuthMenu),"root");
static void Reset(){foreach(var type in new[]{typeof(YouTubeAuthMenu),typeof(YouTubeAuthRuntime)})foreach(var f in type.GetFields(BindingFlags.Static|BindingFlags.NonPublic)){if(f.IsInitOnly)continue;f.SetValue(null,f.FieldType.IsValueType?Activator.CreateInstance(f.FieldType):null);}Probe.Reset();}
static void Test(string n,Action a){Reset();try{a();passed++;Console.WriteLine("PASS "+n);}catch(Exception e){failed++;Console.WriteLine("FAIL "+n+": "+e.GetType().Name+" "+e.Message);}}
static void Main(){
Test("menu startup does not eagerly construct auth page",()=>{string source=Source("Modules/Streamer/StreamerMenu.cs");Check(!source.Contains("YouTubeAuthMenu.Initialize(mainmenumanager)"));var open=source.IndexOf("void SetOpenMenu()");Check(open>0&&!source.Substring(0,open).Contains("TMPTemplate.Create("));});
Test("OFF startup ticks do not create auth HTTP or protected store",()=>{for(int i=0;i<5322;i++)YouTubeAuthRuntime.Tick();Check(Probe.SettingsLoads==0&&Probe.Exchanges==0&&Probe.Restores==0);});
Test("cancelling an unopened auth page does not initialize runtime",()=>{YouTubeAuthRuntime.Cancel();Check(Probe.SettingsLoads==0&&Probe.Exchanges==0&&Probe.Restores==0);});
Test("opening before VersionShower seeds valid text donor",()=>{var m=new MainMenuManager();YouTubeAuthMenu.Show(m);Check(Root!=null&&Root.activeSelf&&TMPTemplate.Ready&&Probe.StreamCloses==1&&Probe.Restores==1);});
Test("missing font does not leave an active partial root",()=>{var m=new MainMenuManager();m.quitButton.Donor=null;try{YouTubeAuthMenu.Show(m);}catch{}Check(Root==null||!Root.activeSelf);Check(Probe.StreamCloses==0);for(int i=0;i<5322;i++)YouTubeAuthMenu.Tick();Check(Probe.Restores==0&&Probe.Warnings<=1);});
Test("failed button construction rolls back entire page",()=>{TMPTemplate.Ready=true;Probe.FailButton="GoogleLinkRemove";var m=new MainMenuManager();try{YouTubeAuthMenu.Show(m);}catch{}Check(Root==null||!Root.activeSelf);Check(!GameObject.All.Any(g=>g.name=="ShellYouTubeAuth"&&g.activeInHierarchy));Check(Probe.StreamCloses==0&&Probe.Restores==0);for(int i=0;i<5322;i++)YouTubeAuthMenu.Tick();});
Test("failed construction can retry once dependency recovers",()=>{TMPTemplate.Ready=true;Probe.FailButton="GoogleLinkRemove";var m=new MainMenuManager();try{YouTubeAuthMenu.Show(m);}catch{}Probe.FailButton=null;YouTubeAuthMenu.Show(m);Check(Root!=null&&Root.activeSelf&&Probe.StreamCloses==1&&Probe.Restores==1);});
Test("hidden page ticks do not initialize auth",()=>{var m=new MainMenuManager();typeof(YouTubeAuthMenu).GetMethod("Initialize",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{m});for(int i=0;i<500;i++)YouTubeAuthMenu.Tick();Check(Probe.Restores==0&&Root!=null&&!Root.activeSelf);});
Test("repeated opening reuses a complete page",()=>{TMPTemplate.Ready=true;var m=new MainMenuManager();YouTubeAuthMenu.Show(m);var first=Root;YouTubeAuthMenu.Hide();YouTubeAuthMenu.Show(m);Check(ReferenceEquals(first,Root)&&Probe.Restores==1);Check(GameObject.All.Count(g=>g.name=="ShellYouTubeAuth"&&!g.dead)==1);});
Test("ESC returns to stream menu without a remaining overlay",()=>{TMPTemplate.Ready=true;YouTubeAuthMenu.Show(new());Probe.Escape=true;YouTubeAuthMenu.Tick();Check(!Root.activeSelf&&Probe.StreamShows==1&&Probe.Cancels==1);});
Test("menu recreation replaces old owner without duplicates",()=>{TMPTemplate.Ready=true;YouTubeAuthMenu.Show(new());var first=Root;YouTubeAuthMenu.Show(new());Check(first.dead&&!first.activeSelf&&!ReferenceEquals(first,Root)&&Root.activeSelf&&Probe.Restores==1);});
Test("destroyed text is not refreshed each frame",()=>{TMPTemplate.Ready=true;YouTubeAuthMenu.Show(new());UnityEngine.Object.Destroy((TMPro.TextMeshPro)Field(typeof(YouTubeAuthMenu),"status"));for(int i=0;i<5322;i++)YouTubeAuthMenu.Tick();Check(Root==null||!Root.activeSelf);});
Test("comments ON reaches runtime initialization only after state guard",()=>{var s=Source("Modules/Streamer/Readcomment.cs");var start=s.IndexOf("public static void CommentFrameTick(");var end=s.IndexOf("private static void TryStartFetch",start);var body=s.Substring(start,end-start);Check(body.IndexOf("YouTubeAuthRuntime.EnsureInitialized();")>body.IndexOf("if (!wanted ||"));Check(body.Contains("GameStates.IsLobby || GameStates.InGame"));});
Test("retained grant after a failed relink keeps the relink action",()=>{TMPTemplate.Ready=true;YouTubeAuthMenu.Show(new());var service=YouTubeAuthRuntime.Service;service.State=YouTubeAuthState.AuthenticationError;service.HasSavedLink=true;service.Revision++;YouTubeAuthMenu.Tick();var button=(TownOfHost.Templates.SimpleButton)Field(typeof(YouTubeAuthMenu),"begin");Check(button.Label.text=="Googleを再連携"&&button.Button.gameObject.activeSelf);service.HasSavedLink=false;service.Revision++;YouTubeAuthMenu.Tick();Check(button.Label.text=="Google連携開始");});
Test("progress revision refreshes text while duplicate linking is hidden",()=>{TMPTemplate.Ready=true;YouTubeAuthMenu.Show(new());var service=YouTubeAuthRuntime.Service;service.State=YouTubeAuthState.Authorizing;service.IsBusy=true;service.MessageText="synthetic validation progress";service.Revision++;YouTubeAuthMenu.Tick();var label=(TMPro.TextMeshPro)Field(typeof(YouTubeAuthMenu),"status");var button=(TownOfHost.Templates.SimpleButton)Field(typeof(YouTubeAuthMenu),"begin");Check(label.text==service.MessageText&&!button.Button.gameObject.activeSelf&&Root.activeSelf);});
Console.WriteLine($"RESULT {passed} passed, {failed} failed (actual auth UI source; simulated Unity lifecycle; no browser/network)");Environment.ExitCode=failed>0?1:0;
}
static string Source(string p)=>File.ReadAllText(Path.Combine(Environment.GetEnvironmentVariable("TOHS_VERSION_SOURCE")??Directory.GetCurrentDirectory(),p));
}
